// v23.xx (gfx27), HIS ORDER (2026-10-12) on the graphics program: "add ALL of this stuff", item 12, richer ground. THE GROUND GETS
// WET. Rain and storms changed what you could hear and see, but the ground looked exactly as dry as on a clear night. Wetness
// (GFX.WET, 0 to 1) now eases toward the rain of the weather in force (rain or storm wets it fully): it soaks in over 20 seconds
// and dries over 90, so a storm that passes leaves the ground wet for a while after. A raid that drops in rain starts wet. While
// it is wet the world is a touch darker (6 percent at full wet) and every lamp throws more of its own colour on the ground
// (its glow up to 1.8 times): the wet sheen. The light pass of the graphics program (gfxLightPass), when it is on, does its own
// sheen and this one stands down. Render only: the tick never draws from the raid stream and does nothing in a bot raid.
function gfxWetTick(dt){
  if(!G||G.sim) return 0;
  var w=wx(), tgt=Math.max(0,Math.min(1,+(w&&w.rain)||0)), d=Math.max(0,Math.min(1,+dt||0));
  if(GFX.wetG!==G){ GFX.wetG=G; GFX.WET=tgt; return GFX.WET; }
  if(GFX.WET<tgt) GFX.WET=Math.min(tgt,GFX.WET+d/20);
  else if(GFX.WET>tgt) GFX.WET=Math.max(tgt,GFX.WET-d/90);
  return GFX.WET;
}
function gfxWet(){ return (GFX.bypass||!G||GFX.wetG!==G)?0:(+GFX.WET||0); }   // how wet the ground is, 0 to 1
function gfxWetSheen(dt,Z,ox,oy,VW,VH){
  var k=gfxWet(), i, L2, fk, n=0, day;
  if(!(k>0.02)||!G||!G.lights) return 0;
  day=isDay();
  wc.save();
  try{
    wc.globalCompositeOperation='source-over'; wc.globalAlpha=1;
    wc.fillStyle='rgba(4,6,10,'+(0.06*k).toFixed(3)+')'; wc.fillRect(0,0,W,H);
    wc.scale(Z,Z); wc.translate(-ox,-oy);
    wc.globalCompositeOperation='lighter';
    for(i=0;i<G.lights.length;i++){
      L2=G.lights[i];
      if(L2.x<ox-80||L2.x>ox+VW+80||L2.y<oy-80||L2.y>oy+VH+80) continue;
      fk=(L2.fl?(.72+.28*Math.sin(G.t*11+L2.f)):1)*wx().lights*(day?tod().lights:1);
      if(fk<=0.02) continue;
      wc.fillStyle=L2.c;
      wc.globalAlpha=(day?.05:.20)*fk*0.8*k; wc.beginPath(); wc.arc(L2.x,L2.y,L2.r*.20,0,6.2832); wc.fill();
      wc.globalAlpha=(day?.025:.10)*fk*0.8*k; wc.beginPath(); wc.arc(L2.x,L2.y,L2.r*.42,0,6.2832); wc.fill();
      n++;
    }
  } finally { wc.restore(); }
  return n;
}

